package vn.edu.hcmute.example3; import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="otp_tokens") public class OtpToken {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private String email; @Column(nullable=false) private String codeHash; @Column(nullable=false) private String purpose; @Column(nullable=false) private Instant expiresAt; private Instant usedAt; protected OtpToken(){} public OtpToken(String email,String hash,String purpose,Instant expiresAt){this.email=email;this.codeHash=hash;this.purpose=purpose;this.expiresAt=expiresAt;} public String getEmail(){return email;} public String getCodeHash(){return codeHash;} public String getPurpose(){return purpose;} public Instant getExpiresAt(){return expiresAt;} public Instant getUsedAt(){return usedAt;} public void consume(){usedAt=Instant.now();}}
